package main

import (
	"flag"
	"fmt"
	"image"
	_ "image/gif"
	_ "image/jpeg"
	_ "image/png"
	"image/color"
	"io"
	"net/http"
	"os"
	"strings"
)

func main() {
	// Create a custom flag set to handle usage manually
	fs := flag.NewFlagSet(os.Args[0], flag.ContinueOnError)

	// Define flags
	version := fs.Bool("version", false, "show PIXterm version")
	credits := fs.Bool("credits", false, "show some love to contributors <3")
	help := fs.Bool("help", false, "prints this message :D LOL")
	dither := fs.Int("d", 0, "dithering mode")
	goCode := fs.Bool("go", false, "output Go code to 'fmt.Print()' the image")
	matte := fs.String("m", "000000", "matte color for transparency or background")
	noBg := fs.Bool("nobg", false, "disable background color")
	scale := fs.Int("s", 0, "scale method")
	termCols := fs.Int("tc", 80, "terminal columns")
	termRows := fs.Int("tr", 24, "terminal rows")

	// Suppress the default usage function
	fs.Usage = func() {}

	// Parse arguments
	err := fs.Parse(os.Args[1:])
	if err != nil {
		os.Exit(1)
	}

	// Handle version flag first (no banner)
	if *version {
		fmt.Println("1.3.2")
		os.Exit(0)
	}

	// Show banner for all other cases
	banner := `   ___  _____  ____
  / _ \/  _/ |/_/ /____ ______ _      Made with love by Eliuk Blau
 / ___// /_>  </ __/ -_) __/  ' \ https://github.com/eliukblau/pixterm
/_/  /___/_/|_|\__/\__/_/ /_/_/_/                1.3.2`

	fmt.Println(banner)
	fmt.Println()

	// Handle credits flag
	if *credits {
		printCredits()
		os.Exit(0)
	}

	// Handle help flag or no image provided
	if *help || fs.NArg() == 0 {
		printUsage()
		os.Exit(0)
	}

	// Get image path/URL
	imagePath := fs.Arg(0)

	// Load image
	img, err := loadImage(imagePath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error loading image: %v\n", err)
		os.Exit(1)
	}

	// Calculate display dimensions
	displayRows := *termRows
	displayCols := *termCols

	// Scale image
	img = scaleImage(img, displayCols, displayRows, *scale)

	// Render image based on dither mode
	matteColor := parseHexColor(*matte)

	if *goCode {
		// Output Go code format
		renderGoCode(img, matteColor, *dither, *noBg)
	} else {
		// Output to terminal
		renderTerminal(img, matteColor, *dither, *noBg)
	}
}

func loadImage(path string) (image.Image, error) {
	var reader io.Reader

	if strings.HasPrefix(path, "http://") || strings.HasPrefix(path, "https://") {
		// Load from URL
		resp, err := http.Get(path)
		if err != nil {
			return nil, err
		}
		defer resp.Body.Close()
		reader = resp.Body
	} else {
		// Load from file
		file, err := os.Open(path)
		if err != nil {
			return nil, err
		}
		defer file.Close()
		reader = file
	}

	img, _, err := image.Decode(reader)
	return img, err
}

func scaleImage(img image.Image, width, height, scaleMethod int) image.Image {
	// For now, just return the original image
	// TODO: Implement proper scaling with different methods
	return img
}

func parseHexColor(hexStr string) color.RGBA {
	// Parse hex color like "FF0000" to RGB
	r, g, b := byte(0), byte(0), byte(0)

	if len(hexStr) >= 6 {
		fmt.Sscanf(hexStr[0:2], "%02x", &r)
		fmt.Sscanf(hexStr[2:4], "%02x", &g)
		fmt.Sscanf(hexStr[4:6], "%02x", &b)
	}

	return color.RGBA{R: r, G: g, B: b, A: 255}
}

func renderTerminal(img image.Image, matte color.RGBA, ditherMode int, noBg bool) {
	// TODO: Implement terminal rendering
	bounds := img.Bounds()
	fmt.Printf("Image size: %dx%d\n", bounds.Dx(), bounds.Dy())
}

func renderGoCode(img image.Image, matte color.RGBA, ditherMode int, noBg bool) {
	// TODO: Implement Go code output
	fmt.Println("fmt.Print(\"test\")")
}

func printUsage() {
	fmt.Println("USAGE:")
	fmt.Println()
	fmt.Println("  executable [options] image/url")
	fmt.Println()
	fmt.Println("  Supported image formats: JPEG, PNG, GIF, BMP, TIFF, WebP.")
	fmt.Println("  Supported URL protocols: HTTP, HTTPS.")
	fmt.Println()
	fmt.Println("OPTIONS:")
	fmt.Println()
	fmt.Println("  -credits")
	fmt.Println("    \tshow some love to contributors <3")
	fmt.Println("  -d mode")
	fmt.Println("    \tdithering mode:")
	fmt.Println("    \t   0 - no dithering (default)")
	fmt.Println("    \t   1 - with blocks")
	fmt.Println("    \t   2 - with chars")
	fmt.Println("  -go")
	fmt.Println("    \toutput Go code to 'fmt.Print()' the image")
	fmt.Println("  -m color")
	fmt.Println("    \tmatte color for transparency or background")
	fmt.Println("    \t(optional, hex format, default: 000000)")
	fmt.Println("  -nobg")
	fmt.Println("    \tdisable background color")
	fmt.Println("    \t(optional, only in dithering mode, ignores matte color)")
	fmt.Println("  -s method")
	fmt.Println("    \tscale method:")
	fmt.Println("    \t   0 - resize (default)")
	fmt.Println("    \t   1 - fill")
	fmt.Println("    \t   2 - fit")
	fmt.Println("  -tc columns")
	fmt.Println("    \tterminal columns (optional, >=2; when piping, default: 80)")
	fmt.Println("  -tr rows")
	fmt.Println("    \tterminal rows (optional, >=2; when piping, default: 24)")
	fmt.Println("  -version")
	fmt.Println("    \tshow PIXterm version")
	fmt.Println("  -help")
	fmt.Println("\tprints this message :D LOL")
	fmt.Println()
}

func printCredits() {
	fmt.Println("CONTRIBUTORS:")
	fmt.Println()
	fmt.Println("  > @disq - https://github.com/disq")
	fmt.Println("      + Original code for image transparency support.")
	fmt.Println()
	fmt.Println("  > @timob - https://github.com/timob")
	fmt.Println("      + Fix for ANSIpixel type: use 8bit color component for output.")
	fmt.Println()
	fmt.Println("  > @HongjiangHuang - https://github.com/HongjiangHuang")
	fmt.Println("      + Original code for image download support.")
	fmt.Println()
	fmt.Println("  > @brutestack - https://github.com/brutestack")
	fmt.Println("      + Color support for Windows (Command Prompt & PowerShell).")
	fmt.Println("      + Original code for disable background color in dithering mode.")
	fmt.Println("      + Original code for output Go code to 'fmt.Print()' the image.")
	fmt.Println()
	fmt.Println("  > @diamondburned - https://github.com/diamondburned")
	fmt.Println("      + NewFromImage() & NewScaledFromImage() for ANSImage API.")
