		}
		defer file.Close()
		reader = file
	}

	img, _, err := image.Decode(reader)
	if err != nil {
		return nil, fmt.Errorf("image: unknown format")
	}
	return img, nil
}

func scaleImage(img image.Image, targetWidth, targetHeight int, scaleMethod int) image.Image {
	bounds := img.Bounds()
	srcWidth := bounds.Dx()
	srcHeight := bounds.Dy()

	// Calculate scaling based on method
	var dstWidth, dstHeight int

	switch scaleMethod {
	case 1: // Fill - maintain aspect ratio and fill the screen
		scaleX := float64(targetWidth) / float64(srcWidth)
		scaleY := float64(targetHeight) / float64(srcHeight)
		if scaleX < scaleY {
			scaleX = scaleY
		}
		dstWidth = int(float64(srcWidth) * scaleX)
		dstHeight = int(float64(srcHeight) * scaleX)
	case 2: // Fit - maintain aspect ratio and fit to screen
		scaleX := float64(targetWidth) / float64(srcWidth)
		scaleY := float64(targetHeight) / float64(srcHeight)
		if scaleX > scaleY {
			scaleX = scaleY
		}
		dstWidth = int(float64(srcWidth) * scaleX)
		dstHeight = int(float64(srcHeight) * scaleX)
	default: // 0 - Resize - just resize to fill the display
		dstWidth = targetWidth
		dstHeight = targetHeight
	}

	// Simple nearest-neighbor scaling
	dst := image.NewRGBA(image.Rect(0, 0, dstWidth, dstHeight))

	for y := 0; y < dstHeight; y++ {
		for x := 0; x < dstWidth; x++ {
			srcX := x * srcWidth / dstWidth
			srcY := y * srcHeight / dstHeight

			// Clamp to bounds
			if srcX >= srcWidth {
				srcX = srcWidth - 1
			}
			if srcY >= srcHeight {
				srcY = srcHeight - 1
			}

			c := img.At(bounds.Min.X+srcX, bounds.Min.Y+srcY)
			dst.Set(x, y, c)
		}
	}

	return dst
}

func parseHexColor(hexStr string) color.RGBA {
	// Parse hex color like "FF0000" to RGB
	r, g, b := uint8(0), uint8(0), uint8(0)

	if len(hexStr) >= 6 {
		// Parse first two hex digits as red
		if val, err := strconv.ParseInt(hexStr[0:2], 16, 8); err == nil {
			r = uint8(val)
		}
		// Parse next two hex digits as green
		if val, err := strconv.ParseInt(hexStr[2:4], 16, 8); err == nil {
			g = uint8(val)
		}
		// Parse last two hex digits as blue
		if val, err := strconv.ParseInt(hexStr[4:6], 16, 8); err == nil {
			b = uint8(val)
		}
	}

	return color.RGBA{R: r, G: g, B: b, A: 255}
}

func rgbaToAnsi(c color.Color) (uint8, uint8, uint8) {
	r, g, b, _ := c.RGBA()
	// RGBA returns 16-bit values, convert to 8-bit
	return uint8(r >> 8), uint8(g >> 8), uint8(b >> 8)
}

func renderTerminal(img image.Image, matte color.RGBA, ditherMode int, noBg bool) {
	bounds := img.Bounds()
	width := bounds.Dx()
	height := bounds.Dy()

