package main

import (
	"flag"
	"fmt"
	"image"
	_ "image/gif"
	_ "image/jpeg"
	_ "image/png"
	"image/color"
	"io"
	"net/http"
	"os"
	"strconv"
	"strings"
)

func main() {
	// Create a custom flag set to handle usage manually
	fs := flag.NewFlagSet(os.Args[0], flag.ContinueOnError)

	// Define flags
	version := fs.Bool("version", false, "show PIXterm version")
	credits := fs.Bool("credits", false, "show some love to contributors <3")
	help := fs.Bool("help", false, "prints this message :D LOL")
	dither := fs.Int("d", 0, "dithering mode")
	goCode := fs.Bool("go", false, "output Go code to 'fmt.Print()' the image")
	matte := fs.String("m", "000000", "matte color for transparency or background")
	noBg := fs.Bool("nobg", false, "disable background color")
	scale := fs.Int("s", 0, "scale method")
	termCols := fs.Int("tc", 80, "terminal columns")
	termRows := fs.Int("tr", 24, "terminal rows")

	// Suppress the default usage function
	fs.Usage = func() {}

	// Parse arguments
	err := fs.Parse(os.Args[1:])
	if err != nil {
		os.Exit(1)
	}

	// Handle version flag first (no banner)
	if *version {
		fmt.Println("1.3.2")
		os.Exit(0)
	}

	// Show banner for all other cases
	banner := `   ___  _____  ____
  / _ \/  _/ |/_/ /____ ______ _      Made with love by Eliuk Blau
 / ___// /_>  </ __/ -_) __/  ' \ https://github.com/eliukblau/pixterm
/_/  /___/_/|_|\__/\__/_/ /_/_/_/                1.3.2`

	fmt.Println(banner)
	fmt.Println()

	// Handle credits flag
	if *credits {
		printCredits()
		os.Exit(0)
	}

	// Handle help flag or no image provided
	if *help || fs.NArg() == 0 {
		printUsage()
		os.Exit(0)
	}

	// Get image path/URL
	imagePath := fs.Arg(0)

	// Load image
	img, err := loadImage(imagePath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "[PIXTERM ERROR] %s\n", err)
		os.Exit(1)
	}

	// Scale image
	displayWidth := *termCols
	displayHeight := *termRows * 2 // Each character cell represents 2 pixels in height

	img = scaleImage(img, displayWidth, displayHeight, *scale)

	// Render image based on dither mode
	matteColor := parseHexColor(*matte)

	if *goCode {
		// Output Go code format
		renderGoCode(img, matteColor, *dither, *noBg)
	} else {
		// Output to terminal
		renderTerminal(img, matteColor, *dither, *noBg)
	}
}

func loadImage(path string) (image.Image, error) {
	var reader io.Reader

	if strings.HasPrefix(path, "http://") || strings.HasPrefix(path, "https://") {
		// Load from URL
		resp, err := http.Get(path)
		if err != nil {
			return nil, fmt.Errorf("image: unknown format")
		}
		defer resp.Body.Close()
		reader = resp.Body
	} else {
		// Load from file
		file, err := os.Open(path)
		if err != nil {
			return nil, fmt.Errorf("image: unknown format")
		}
		defer file.Close()
		reader = file
	}

	img, _, err := image.Decode(reader)
	if err != nil {
		return nil, fmt.Errorf("image: unknown format")
	}
	return img, nil
}

func scaleImage(img image.Image, targetWidth, targetHeight int, scaleMethod int) image.Image {
	bounds := img.Bounds()
	srcWidth := bounds.Dx()
	srcHeight := bounds.Dy()

	// Calculate scaling based on method
	var dstWidth, dstHeight int

	switch scaleMethod {
	case 1: // Fill - maintain aspect ratio and fill the screen
		scaleX := float64(targetWidth) / float64(srcWidth)
		scaleY := float64(targetHeight) / float64(srcHeight)
		if scaleX < scaleY {
			scaleX = scaleY
		}
		dstWidth = int(float64(srcWidth) * scaleX)
		dstHeight = int(float64(srcHeight) * scaleX)
	case 2: // Fit - maintain aspect ratio and fit to screen
		scaleX := float64(targetWidth) / float64(srcWidth)
		scaleY := float64(targetHeight) / float64(srcHeight)
		if scaleX > scaleY {
			scaleX = scaleY
		}
		dstWidth = int(float64(srcWidth) * scaleX)
		dstHeight = int(float64(srcHeight) * scaleX)
	default: // 0 - Resize - just resize to fill the display
		dstWidth = targetWidth
		dstHeight = targetHeight
	}

	// Bilinear interpolation scaling
	dst := image.NewRGBA(image.Rect(0, 0, dstWidth, dstHeight))

	for y := 0; y < dstHeight; y++ {
		for x := 0; x < dstWidth; x++ {
			srcX := float64(x) * float64(srcWidth) / float64(dstWidth)
			srcY := float64(y) * float64(srcHeight) / float64(dstHeight)

			// Bilinear interpolation
			x1 := int(srcX)
			y1 := int(srcY)
			x2 := x1 + 1
			y2 := y1 + 1

			// Clamp to bounds
			if x1 < 0 {
				x1 = 0
			}
			if x2 >= srcWidth {
				x2 = srcWidth - 1
			}
			if y1 < 0 {
				y1 = 0
			}
			if y2 >= srcHeight {
				y2 = srcHeight - 1
			}

			// Get the four corner pixels
			c11 := img.At(bounds.Min.X+x1, bounds.Min.Y+y1)
			c21 := img.At(bounds.Min.X+x2, bounds.Min.Y+y1)
			c12 := img.At(bounds.Min.X+x1, bounds.Min.Y+y2)
			c22 := img.At(bounds.Min.X+x2, bounds.Min.Y+y2)

			// Interpolation factors
			fx := srcX - float64(x1)
			fy := srcY - float64(y1)

			// Interpolate
			c := interpolateColor(c11, c21, c12, c22, fx, fy)
			dst.Set(x, y, c)
		}
	}

	return dst
}

func interpolateColor(c11, c21, c12, c22 color.Color, fx, fy float64) color.Color {
	// Convert to RGBA
	r11, g11, b11, a11 := c11.RGBA()
	r21, g21, b21, a21 := c21.RGBA()
	r12, g12, b12, a12 := c12.RGBA()
	r22, g22, b22, a22 := c22.RGBA()

	// Normalize from 16-bit to floating point 0-1
	r11f := float64(r11) / 65535.0
	g11f := float64(g11) / 65535.0
	b11f := float64(b11) / 65535.0
	a11f := float64(a11) / 65535.0

	r21f := float64(r21) / 65535.0
	g21f := float64(g21) / 65535.0
	b21f := float64(b21) / 65535.0
	a21f := float64(a21) / 65535.0

	r12f := float64(r12) / 65535.0
	g12f := float64(g12) / 65535.0
	b12f := float64(b12) / 65535.0
	a12f := float64(a12) / 65535.0

	r22f := float64(r22) / 65535.0
	g22f := float64(g22) / 65535.0
	b22f := float64(b22) / 65535.0
	a22f := float64(a22) / 65535.0

	// Bilinear interpolation
	r := r11f*(1-fx)*(1-fy) + r21f*fx*(1-fy) + r12f*(1-fx)*fy + r22f*fx*fy
	g := g11f*(1-fx)*(1-fy) + g21f*fx*(1-fy) + g12f*(1-fx)*fy + g22f*fx*fy
	b := b11f*(1-fx)*(1-fy) + b21f*fx*(1-fy) + b12f*(1-fx)*fy + b22f*fx*fy
	a := a11f*(1-fx)*(1-fy) + a21f*fx*(1-fy) + a12f*(1-fx)*fy + a22f*fx*fy

	// Convert back to 8-bit
	return color.RGBA{
		R: uint8(r * 255),
		G: uint8(g * 255),
		B: uint8(b * 255),
		A: uint8(a * 255),
	}
}

func parseHexColor(hexStr string) color.RGBA {
	// Parse hex color like "FF0000" to RGB
	r, g, b := uint8(0), uint8(0), uint8(0)

	if len(hexStr) >= 6 {
		// Parse first two hex digits as red
		if val, err := strconv.ParseInt(hexStr[0:2], 16, 8); err == nil {
			r = uint8(val)
		}
		// Parse next two hex digits as green
		if val, err := strconv.ParseInt(hexStr[2:4], 16, 8); err == nil {
			g = uint8(val)
		}
		// Parse last two hex digits as blue
		if val, err := strconv.ParseInt(hexStr[4:6], 16, 8); err == nil {
			b = uint8(val)
		}
	}

	return color.RGBA{R: r, G: g, B: b, A: 255}
}

func rgbaToAnsi(c color.Color) (uint8, uint8, uint8) {
	r, g, b, _ := c.RGBA()
	// RGBA returns 16-bit values, convert to 8-bit
	return uint8(r >> 8), uint8(g >> 8), uint8(b >> 8)
}

func renderTerminal(img image.Image, matte color.RGBA, ditherMode int, noBg bool) {
	bounds := img.Bounds()
	width := bounds.Dx()
	height := bounds.Dy()

	// Render character by character
	// Each character cell shows 2 rows of pixels
	for y := 0; y < height; y += 2 {
		for x := 0; x < width; x++ {
			// Get colors for this cell
			var topColor, bottomColor color.Color

			// Top pixel (foreground in the cell)
			if y+1 < height {
				topColor = img.At(bounds.Min.X+x, bounds.Min.Y+y+1)
			} else {
				topColor = matte
			}

			// Bottom pixel (background in the cell)
			bottomColor = img.At(bounds.Min.X+x, bounds.Min.Y+y)

			// Convert to 8-bit RGB
			bR, bG, bB := rgbaToAnsi(bottomColor)
			tR, tG, tB := rgbaToAnsi(topColor)

			// Output ANSI escape codes
			// Background color for bottom pixel, foreground color for top pixel
			fmt.Printf("[48;2;%d;%d;%dm[38;2;%d;%d;%dm▄", bR, bG, bB, tR, tG, tB)
		}
		fmt.Printf("[0m\n")
	}
}

func renderGoCode(img image.Image, matte color.RGBA, ditherMode int, noBg bool) {
