func parseHexColor(hexStr string) color.RGBA {
	// Parse hex color like "FF0000" to RGB
	r, g, b := uint8(0), uint8(0), uint8(0)

	if len(hexStr) >= 6 {
		// Parse first two hex digits as red
		if val, err := strconv.ParseInt(hexStr[0:2], 16, 8); err == nil {
			r = uint8(val)
		}
		// Parse next two hex digits as green
		if val, err := strconv.ParseInt(hexStr[2:4], 16, 8); err == nil {
