		for x := 0; x < displayWidth; x++ {
			// Map display coordinates to source image coordinates
			// Each display character represents a cell that shows 2 rows of pixels

			// For the bottom half block (background), we show the "lower" pixel
			// For the upper half block (foreground), we show the "upper" pixel

