			bottomColor := averagePixels(img, bounds.Min.X+srcX, bounds.Min.Y+srcY, bounds.Min.X+srcX2, bounds.Min.Y+srcY2Bottom)
			topColor := averagePixels(img, bounds.Min.X+srcX, bounds.Min.Y+srcYTop, bounds.Min.X+srcX2, bounds.Min.Y+srcY2Top)

