package main

import (
	"fmt"
	"image"
	"image/color"
	"image/png"
	"os"
)

func main() {
	// Create a 2x2 red image
	img := image.NewRGBA(image.Rect(0, 0, 2, 2))
	for y := 0; y < 2; y++ {
		for x := 0; x < 2; x++ {
			img.Set(x, y, color.RGBA{255, 0, 0, 255})
		}
	}
	file, _ := os.Create("test_2x2_red.png")
	png.Encode(file, img)
	file.Close()

	// Create a 2x2 blue image
	img = image.NewRGBA(image.Rect(0, 0, 2, 2))
	for y := 0; y < 2; y++ {
		for x := 0; x < 2; x++ {
			img.Set(x, y, color.RGBA{0, 0, 255, 255})
		}
	}
	file, _ = os.Create("test_2x2_blue.png")
	png.Encode(file, img)
	file.Close()

	// Create a 1x2 half-red-half-blue
	img = image.NewRGBA(image.Rect(0, 0, 1, 2))
	img.Set(0, 0, color.RGBA{255, 0, 0, 255})
	img.Set(0, 1, color.RGBA{0, 0, 255, 255})
	file, _ = os.Create("test_1x2.png")
	png.Encode(file, img)
	file.Close()

	fmt.Println("Created test images")
