package main

import (
	"flag"
	"fmt"
	"image"
	_ "image/gif"
	_ "image/jpeg"
	_ "image/png"
	"image/color"
	"io"
	"net/http"
	"os"
	"strconv"
	"strings"
)

func main() {
	// Create a custom flag set to handle usage manually
	fs := flag.NewFlagSet(os.Args[0], flag.ContinueOnError)

	// Define flags
	version := fs.Bool("version", false, "show PIXterm version")
	credits := fs.Bool("credits", false, "show some love to contributors <3")
	help := fs.Bool("help", false, "prints this message :D LOL")
	dither := fs.Int("d", 0, "dithering mode")
	goCode := fs.Bool("go", false, "output Go code to 'fmt.Print()' the image")
	matte := fs.String("m", "000000", "matte color for transparency or background")
	noBg := fs.Bool("nobg", false, "disable background color")
	scale := fs.Int("s", 0, "scale method")
	termCols := fs.Int("tc", 80, "terminal columns")
	termRows := fs.Int("tr", 24, "terminal rows")

	// Suppress the default usage function
	fs.Usage = func() {}

	// Parse arguments
	err := fs.Parse(os.Args[1:])
	if err != nil {
		os.Exit(1)
	}

	// Handle version flag first (no banner)
	if *version {
		fmt.Println("1.3.2")
		os.Exit(0)
	}

	// Show banner for all other cases
	banner := `   ___  _____  ____
  / _ \/  _/ |/_/ /____ ______ _      Made with love by Eliuk Blau
 / ___// /_>  </ __/ -_) __/  ' \ https://github.com/eliukblau/pixterm
/_/  /___/_/|_|\__/\__/_/ /_/_/_/                1.3.2`

	fmt.Println(banner)
	fmt.Println()

	// Handle credits flag
	if *credits {
		printCredits()
		os.Exit(0)
	}

	// Handle help flag or no image provided
	if *help || fs.NArg() == 0 {
		printUsage()
		os.Exit(0)
	}

	// Validate terminal dimensions
	if *termCols < 2 || *termRows < 2 {
		fmt.Fprintf(os.Stderr, "[PIXTERM ERROR] terminal dimensions must be >= 2\n")
		os.Exit(2)
	}

	// Get image path/URL
	imagePath := fs.Arg(0)

	// Load image
	img, err := loadImage(imagePath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "[PIXTERM ERROR] %s\n", err)
		os.Exit(1)
	}

	// Render image based on dither mode
	matteColor := parseHexColor(*matte)

	if *goCode {
		// Output Go code format
		renderGoCodeFormat(img, *termCols, *termRows, matteColor, *dither, *noBg, *scale)
	} else {
		// Output to terminal
		renderToTerminal(img, *termCols, *termRows, matteColor, *dither, *noBg, *scale)
	}
}

func loadImage(path string) (image.Image, error) {
	var reader io.Reader

	if strings.HasPrefix(path, "http://") || strings.HasPrefix(path, "https://") {
		// Load from URL
		resp, err := http.Get(path)
		if err != nil {
			return nil, fmt.Errorf("image: unknown format")
		}
		defer resp.Body.Close()
		reader = resp.Body
	} else {
		// Load from file
		file, err := os.Open(path)
		if err != nil {
			return nil, fmt.Errorf("image: unknown format")
		}
		defer file.Close()
		reader = file
	}

	img, _, err := image.Decode(reader)
	if err != nil {
		return nil, fmt.Errorf("image: unknown format")
	}
	return img, nil
}

func parseHexColor(hexStr string) color.RGBA {
	// Parse hex color like "FF0000" to RGB
	r, g, b := uint8(0), uint8(0), uint8(0)

	if len(hexStr) >= 6 {
		// Parse first two hex digits as red
		if val, err := strconv.ParseInt(hexStr[0:2], 16, 8); err == nil {
			r = uint8(val)
		}
		// Parse next two hex digits as green
		if val, err := strconv.ParseInt(hexStr[2:4], 16, 8); err == nil {
			g = uint8(val)
		}
		// Parse last two hex digits as blue
		if val, err := strconv.ParseInt(hexStr[4:6], 16, 8); err == nil {
			b = uint8(val)
		}
	}

	return color.RGBA{R: r, G: g, B: b, A: 255}
}

func rgbaToAnsi(c color.Color) (uint8, uint8, uint8) {
	r, g, b, _ := c.RGBA()
	// RGBA returns 16-bit values, convert to 8-bit
	return uint8(r >> 8), uint8(g >> 8), uint8(b >> 8)
}

func averagePixels(img image.Image, x1, y1, x2, y2 int) color.Color {
	// Average pixels in the rectangle (x1,y1) to (x2,y2)
	bounds := img.Bounds()

	// Clamp bounds
	if x1 < bounds.Min.X {
		x1 = bounds.Min.X
	}
	if y1 < bounds.Min.Y {
		y1 = bounds.Min.Y
	}
	if x2 > bounds.Max.X {
		x2 = bounds.Max.X
	}
	if y2 > bounds.Max.Y {
		y2 = bounds.Max.Y
	}

	var sumR, sumG, sumB, sumA float64
	count := 0

	for y := y1; y < y2; y++ {
		for x := x1; x < x2; x++ {
			c := img.At(x, y)
			r, g, b, a := c.RGBA()
			sumR += float64(r >> 8)
			sumG += float64(g >> 8)
			sumB += float64(b >> 8)
			sumA += float64(a >> 8)
			count++
		}
	}

	if count == 0 {
		return color.RGBA{0, 0, 0, 255}
	}

	return color.RGBA{
		R: uint8(sumR / float64(count)),
		G: uint8(sumG / float64(count)),
		B: uint8(sumB / float64(count)),
		A: uint8(sumA / float64(count)),
	}
}

func renderToTerminal(img image.Image, termCols, termRows int, matte color.RGBA, ditherMode int, noBg bool, scaleMethod int) {
	bounds := img.Bounds()
	srcWidth := bounds.Dx()
	srcHeight := bounds.Dy()

	// Calculate display dimensions based on scale method
	var displayWidth, displayHeight int

	switch scaleMethod {
	case 1: // Fill - maintain aspect ratio and fill the screen
		scaleX := float64(termCols) / float64(srcWidth)
		scaleY := float64(termRows*2) / float64(srcHeight) // Each terminal row = 2 image rows
		if scaleX < scaleY {
			scaleX = scaleY
		}
		displayWidth = int(float64(srcWidth) * scaleX)
		displayHeight = int(float64(srcHeight) * scaleX)
	case 2: // Fit - maintain aspect ratio and fit to screen
		scaleX := float64(termCols) / float64(srcWidth)
		scaleY := float64(termRows*2) / float64(srcHeight)
		if scaleX > scaleY {
			scaleX = scaleY
		}
		displayWidth = int(float64(srcWidth) * scaleX)
		displayHeight = int(float64(srcHeight) * scaleX)
	default: // 0 - Resize - just resize to fill the display
		displayWidth = termCols
		displayHeight = termRows * 2
	}

	// Render line by line
	for y := 0; y < displayHeight; y += 2 {
		for x := 0; x < displayWidth; x++ {
			// Map display coordinates to source image coordinates
			srcX := x * srcWidth / displayWidth
			srcY := y * srcHeight / displayHeight

			srcX2 := (x + 1) * srcWidth / displayWidth
			srcY2 := (y + 2) * srcHeight / displayHeight

			// Get bottom and top colors for this cell
			// Bottom half of the cell: pixels at srcY to srcY+1
			// Top half of the cell: pixels at srcY+1 to srcY+2

			bottomY := srcY + srcHeight/(displayHeight/2)
			if bottomY > srcY2 {
				bottomY = srcY2
			}

			bottomColor := averagePixels(img, bounds.Min.X+srcX, bounds.Min.Y+srcY, bounds.Min.X+srcX2, bounds.Min.Y+bottomY)
			topColor := averagePixels(img, bounds.Min.X+srcX, bounds.Min.Y+bottomY, bounds.Min.X+srcX2, bounds.Min.Y+srcY2)

			// Convert to 8-bit RGB
			bR, bG, bB := rgbaToAnsi(bottomColor)
			tR, tG, tB := rgbaToAnsi(topColor)

			// Output ANSI escape codes
			// Background color for bottom pixel, foreground color for top pixel
			fmt.Printf("[48;2;%d;%d;%dm[38;2;%d;%d;%dm▄", bR, bG, bB, tR, tG, tB)
		}
		fmt.Printf("[0m\n")
	}
}

func renderGoCodeFormat(img image.Image, termCols, termRows int, matte color.RGBA, ditherMode int, noBg bool, scaleMethod int) {
	// TODO: Implement Go code output
	fmt.Println("fmt.Print(\"test\")")
}

func printUsage() {
	fmt.Println("USAGE:")
	fmt.Println()
	fmt.Println("  executable [options] image/url")
	fmt.Println()
	fmt.Println("  Supported image formats: JPEG, PNG, GIF, BMP, TIFF, WebP.")
	fmt.Println("  Supported URL protocols: HTTP, HTTPS.")
