	fmt.Println("    \tterminal columns (optional, >=2; when piping, default: 80)")
	fmt.Println("  -tr rows")
	fmt.Println("    \tterminal rows (optional, >=2; when piping, default: 24)")
	fmt.Println("  -version")
	fmt.Println("    \tshow PIXterm version")
	fmt.Println("  -help")
