	for y := 0; y < scaledBounds.Dy(); y += 2 {
		for x := 0; x < scaledBounds.Dx(); x++ {
			// Get bottom and top pixels from scaled image
			bottomColor := scaledImg.At(scaledBounds.Min.X+x, scaledBounds.Min.Y+y)
			var topColor color.Color
			if y+1 < scaledBounds.Dy() {
				topColor = scaledImg.At(scaledBounds.Min.X+x, scaledBounds.Min.Y+y+1)
			} else {
