  / _ \/  _/ |/_/ /____ ______ _      Made with love by Eliuk Blau
 / ___// /_>  </ __/ -_) __/  ' \ https://github.com/eliukblau/pixterm
/_/  /___/_/|_|\__/\__/_/ /_/_/_/                1.3.2`

	fmt.Println(banner)
	fmt.Println()

	// Handle credits flag
	if *credits {
		printCredits()
		os.Exit(0)
	}

	// Handle help flag or no image provided
	if *help || fs.NArg() == 0 {
		printUsage()
		os.Exit(0)
	}

	// Validate terminal dimensions
	if *termCols < 2 || *termRows < 2 {
		fmt.Fprintf(os.Stderr, "[PIXTERM ERROR] terminal dimensions must be >= 2\n")
		os.Exit(2)
	}

	// Get image path/URL
	imagePath := fs.Arg(0)

	// Load image
	img, err := loadImage(imagePath)
	if err != nil {
		fmt.Fprintf(os.Stderr, "[PIXTERM ERROR] %s\n", err)
		os.Exit(1)
	}

	// Render image based on dither mode
	matteColor := parseHexColor(*matte)

	if *goCode {
		// Output Go code format
		renderGoCodeFormat(img, *termCols, *termRows, matteColor, *dither, *noBg, *scale)
	} else {
		// Output to terminal
		renderToTerminal(img, *termCols, *termRows, matteColor, *dither, *noBg, *scale)
	}
}

func loadImage(path string) (image.Image, error) {
	var reader io.Reader

	if strings.HasPrefix(path, "http://") || strings.HasPrefix(path, "https://") {
		// Load from URL
		resp, err := http.Get(path)
		if err != nil {
			return nil, fmt.Errorf("image: unknown format")
		}
		defer resp.Body.Close()
		reader = resp.Body
	} else {
		// Load from file
		file, err := os.Open(path)
		if err != nil {
			return nil, fmt.Errorf("image: unknown format")
		}
		defer file.Close()
		reader = file
	}

	img, _, err := image.Decode(reader)
	if err != nil {
		return nil, fmt.Errorf("image: unknown format")
	}
	return img, nil
}

func parseHexColor(hexStr string) color.RGBA {
	// Parse hex color like "FF0000" to RGB
	r, g, b := uint8(0), uint8(0), uint8(0)

	if len(hexStr) >= 6 {
		// Parse first two hex digits as red
		if val, err := strconv.ParseInt(hexStr[0:2], 16, 8); err == nil {
			r = uint8(val)
		}
		// Parse next two hex digits as green
		if val, err := strconv.ParseInt(hexStr[2:4], 16, 8); err == nil {
			g = uint8(val)
		}
		// Parse last two hex digits as blue
		if val, err := strconv.ParseInt(hexStr[4:6], 16, 8); err == nil {
			b = uint8(val)
		}
	}

	return color.RGBA{R: r, G: g, B: b, A: 255}
}

func rgbaToAnsi(c color.Color) (uint8, uint8, uint8) {
	r, g, b, _ := c.RGBA()
	// RGBA returns 16-bit values, convert to 8-bit
	return uint8(r >> 8), uint8(g >> 8), uint8(b >> 8)
}

func getPixelAt(img image.Image, x, y int) color.Color {
	bounds := img.Bounds()
	if x < bounds.Min.X {
		x = bounds.Min.X
	}
	if x >= bounds.Max.X {
		x = bounds.Max.X - 1
	}
	if y < bounds.Min.Y {
		y = bounds.Min.Y
	}
	if y >= bounds.Max.Y {
		y = bounds.Max.Y - 1
	}
	return img.At(x, y)
}

func averageColors(colors []color.Color) color.Color {
	if len(colors) == 0 {
		return color.RGBA{0, 0, 0, 255}
	}

	var sumR, sumG, sumB, sumA float64
	for _, c := range colors {
		r, g, b, a := c.RGBA()
		sumR += float64(r >> 8)
		sumG += float64(g >> 8)
		sumB += float64(b >> 8)
		sumA += float64(a >> 8)
	}

	count := float64(len(colors))
	return color.RGBA{
		R: uint8(sumR / count),
		G: uint8(sumG / count),
		B: uint8(sumB / count),
		A: uint8(sumA / count),
	}
}

func renderToTerminal(img image.Image, termCols, termRows int, matte color.RGBA, ditherMode int, noBg bool, scaleMethod int) {
	bounds := img.Bounds()
	srcWidth := bounds.Dx()
	srcHeight := bounds.Dy()

	// Calculate display dimensions based on scale method
	var displayWidth, displayHeight int

	switch scaleMethod {
	case 1: // Fill - maintain aspect ratio and fill the screen
		scaleX := float64(termCols) / float64(srcWidth)
		scaleY := float64(termRows*2) / float64(srcHeight) // Each terminal row = 2 image rows
		if scaleX < scaleY {
			scaleX = scaleY
		}
		displayWidth = int(float64(srcWidth) * scaleX)
		displayHeight = int(float64(srcHeight) * scaleX)
	case 2: // Fit - maintain aspect ratio and fit to screen
		scaleX := float64(termCols) / float64(srcWidth)
		scaleY := float64(termRows*2) / float64(srcHeight)
		if scaleX > scaleY {
			scaleX = scaleY
		}
		displayWidth = int(float64(srcWidth) * scaleX)
		displayHeight = int(float64(srcHeight) * scaleX)
	default: // 0 - Resize - just resize to fill the display
		displayWidth = termCols
		displayHeight = termRows * 2
	}

	// Create a scaled image for rendering
	scaledImg := scaleImage(img, displayWidth, displayHeight)
	scaledBounds := scaledImg.Bounds()

	// Render line by line
	for y := 0; y < scaledBounds.Dy(); y += 2 {
		for x := 0; x < scaledBounds.Dx(); x++ {
			// Get bottom and top pixels from scaled image
			bottomColor := scaledImg.At(scaledBounds.Min.X+x, scaledBounds.Min.Y+y)
			var topColor color.Color
			if y+1 < scaledBounds.Dy() {
				topColor = scaledImg.At(scaledBounds.Min.X+x, scaledBounds.Min.Y+y+1)
			} else {
				topColor = matte
			}

			// Convert to 8-bit RGB
			bR, bG, bB := rgbaToAnsi(bottomColor)
			tR, tG, tB := rgbaToAnsi(topColor)

			// Output ANSI escape codes
			fmt.Printf("[48;2;%d;%d;%dm[38;2;%d;%d;%dm▄", bR, bG, bB, tR, tG, tB)
		}
		fmt.Printf("[0m\n")
	}
}

func scaleImage(img image.Image, targetWidth, targetHeight int) image.Image {
	bounds := img.Bounds()
	srcWidth := bounds.Dx()
	srcHeight := bounds.Dy()

	// Create scaled image using nearest neighbor with averaging
	scaledImg := image.NewRGBA(image.Rect(0, 0, targetWidth, targetHeight))

	for y := 0; y < targetHeight; y++ {
		for x := 0; x < targetWidth; x++ {
			// Calculate the region in the source image that maps to this pixel
			srcX1 := x * srcWidth / targetWidth
			srcX2 := (x + 1) * srcWidth / targetWidth
			srcY1 := y * srcHeight / targetHeight
			srcY2 := (y + 1) * srcHeight / targetHeight

			// Collect pixels in this region
			var colors []color.Color
			for sy := srcY1; sy < srcY2; sy++ {
				for sx := srcX1; sx < srcX2; sx++ {
					colors = append(colors, img.At(bounds.Min.X+sx, bounds.Min.Y+sy))
				}
			}

			// Average the colors
			avg := averageColors(colors)
			scaledImg.Set(x, y, avg)
		}
	}

	return scaledImg
}

